rep("#define PES_JK_TETHER     0.025   // (m) tope de la correa de distancia maxima\n",
    "#define PES_JK_TETHER     0.020   // (m) tope de la correa de distancia maxima (x la parte libre, ver pesJkFree)\n")

rep("float pesPinRest(ParticleRest r) { return (s_flags & 256) ? float((r.skin.w >> 2) & 63) / 63.0 : r.posPin.w; }\n",
    "// (16/11) campera: 1 = tela libre (a mas de ~3.5 cm de las otras mallas de la campera), 0 = fija al esqueleto. Grilla de 2 cm\n"
    "// en la pose de armado: x -0.38..0.38, y 0.95..1.63, z -0.13..0.19 (39 x 35 x 17 celdas, un bit por celda), interpolada.\n"
    "static const uint pesJkGrid[726] = {\n" + GRID + "};\n"
    "float pesJkCell(int3 c)\n"
    "{\n"
    "    if (any(c < 0) || c.x >= 39 || c.y >= 35 || c.z >= 17) return 0.0;\n"
    "    uint i = (uint(c.x) * 35u + uint(c.y)) * 17u + uint(c.z);\n"
    "    return float((pesJkGrid[i >> 5] >> (i & 31u)) & 1u);\n"
    "}\n"
    "float pesJkFree(float3 q)\n"
    "{\n"
    "    float3 g = (q - float3(-0.38, 0.95, -0.13)) / 0.02;\n"
    "    int3 c = int3(floor(g));\n"
    "    float3 f = g - float3(c);\n"
    "    float a = lerp(lerp(pesJkCell(c),                 pesJkCell(c + int3(0, 0, 1)), f.z),\n"
    "                   lerp(pesJkCell(c + int3(0, 1, 0)), pesJkCell(c + int3(0, 1, 1)), f.z), f.y);\n"
    "    float b = lerp(lerp(pesJkCell(c + int3(1, 0, 0)), pesJkCell(c + int3(1, 0, 1)), f.z),\n"
    "                   lerp(pesJkCell(c + int3(1, 1, 0)), pesJkCell(c + int3(1, 1, 1)), f.z), f.y);\n"
    "    return smoothstep(0.5, 1.0, lerp(a, b, f.x)) * (1.0 - smoothstep(0.16, 0.20, abs(q.x)));   // mangas fijas\n"
    "}\n"
    "float pesPinRest(ParticleRest r)\n"
    "{\n"
    "    float pn = (s_flags & 256) ? float((r.skin.w >> 2) & 63) / 63.0 : r.posPin.w;\n"
    "    if (PES_IS_JACKET) pn = max(pn, 1.0 - pesJkFree(r.posPin.xyz));   // (16/11) campera: fija donde toca otras mallas\n"
    "    return pn;\n"
    "}\n")

rep("    if (s_flags & 256) return float((g_rest[p].skin.w >> 2) & 63) / 63.0;\n    return g_rest[p].posPin.w;\n}\n",
    "    return pesPinRest(g_rest[p]);   // (16/11) misma regla que pesPinRest (campera)\n}\n")

rep("        if (PES_IS_JACKET) maxD0 = min(maxD0, PES_JK_TETHER);   // (15/11 c)\n",
    "        if (PES_IS_JACKET) maxD0 = min(maxD0, PES_JK_TETHER * pesJkFree(g_rest[p].posPin.xyz));   // (16/11) solo la parte libre\n")

# las restricciones traen sus puntas fijas marcadas por el mod (cn.w): la campera fija con pesJkFree tambien queda fija ahi
rep("    float wb = (cn.w & (tuckedPins ? 16u : 4u)) ? 0.0 : 1.0;\n",
    "    float wb = (cn.w & (tuckedPins ? 16u : 4u)) ? 0.0 : 1.0;\n"
    "    if (PES_IS_JACKET) { if (pinOf(cn.x) >= 0.999) wa = 0.0; if (pinOf(cn.y) >= 0.999) wb = 0.0; }   // (16/11) campera\n")

